+Future<bool> stopDetachedProcess(int pid) async {
+  try {
+    final ok = Process.killPid(pid, ProcessSignal.sigterm);
+    if (ok != true) return false;
+    await Future<void>.delayed(const Duration(milliseconds: 400));
