Future<String> _toolText(AgentTool tool, Map<String, dynamic> arguments) async {
  final result = await tool.execute(arguments, null, null);
  return result.content.whereType<TextContent>().map((c) => c.text).join();
}

void main() {
  test('debug bash tool adoption path', () async {
    final workspace = await Directory.systemTemp.createTemp('dbg2201t-');
    addTearDown(() => workspace.delete(recursive: true));
    final shell = LocalExecutionEnv(cwd: workspace.path);
    // 1) raw exec on the same env the tool uses
    final raw = await shell.exec(
      'nohup sleep 777001 >/dev/null 2>&1 & echo launched',
      options: ShellExecOptions(cwd: workspace.path),
    );
    print('DBG raw survivors: ${raw.valueOrNull!.survivors}');
    Process.run('pkill', ['-f', 'sleep 777001']);
    // 2) the tool path
    final marker = 777002;
    final registry = ShellJobRegistry(env: LocalExecutionEnv(cwd: workspace.path));
    print('DBG jobs.isSupported: ${registry.isSupported}');
    final tool = shellTool(LocalExecutionEnv(cwd: workspace.path), jobs: registry);
    final text = await _toolText(tool, {'command': 'nohup sleep $marker >/dev/null 2>&1 & echo launched'});
    print('DBG tool text: $text');
    final adopted = [for (final e in registry.jobs) if (e.isAdopted) e];
    print('DBG adopted: ${adopted.map((a) => '${a.id} pid ${a.pid}')}');
    for (final a in adopted) { await a.stop(); }
    Process.run('pkill', ['-f', 'sleep 77700']);
  }, timeout: Timeout(Duration(seconds: 60)));
}
