import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

final class _FakeEnv implements ExecutionEnv, BackgroundShell {
  final MemoryExecutionEnv _delegate = MemoryExecutionEnv(cwd: '/w');
  @override
  bool get backgroundJobsSupported => true;
  @override
  Future<Result<ShellJob, ExecutionError>> startShellJob(String command,
      {required String id, required String logPath, ShellExecOptions? options}) async =>
      Err(ExecutionError(ExecutionErrorCode.shellUnavailable, 'fake'));
  @override
  dynamic noSuchMethod(Invocation invocation) => _delegate.noSuchMethod(invocation);
}

void main() {
  test('double captureLostJobs double-adopts live manifest entries', () async {
    final started = <String>[];
    final registry = ShellJobRegistry(
      env: _FakeEnv(),
      onStart: (e) => started.add(e.id),
    );
    // boot #1 adopts the live manifest entry
    registry.adoptRunningEntry(id: 'sh-9-prev', command: 'watch.sh', pid: 4242);
    // boot #2 (second runHeadless on the same instance): the entry is still
    // in the manifest and still alive -> reconcile keeps it -> re-adopt
    registry.adoptRunningEntry(id: 'sh-9-prev', command: 'watch.sh', pid: 4242);
    final sameId = registry.jobs.where((e) => e.id == 'sh-9-prev').length;
    print('DBG entries with id sh-9-prev: $sameId, started fired: ${started.length}');
    expect(sameId, 1, reason: 'adoptRunningEntry should be idempotent');
  }, timeout: Timeout(Duration(seconds: 30)));
}
EOF
